{
  "title": "The Clockwork Rescue",
  "gate_token": "rNTBc8PGjkpQoG7dBjEcaQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers gather at the ruined city's edge.",
      "visual_description": "A shattered archway marks the entrance to a fallen royal city, with crumbling towers and tattered banners in the distance. The glass_diver adjusts his helmet, Mara_the_cartographer studies a map, the oracle_lamp glows dimly on a stone, the sleeping_tax_collector snores against a pillar, and the tin_fox stands alert.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The glass_diver tests a window for passage.",
      "visual_description": "The glass_diver presses his helmet against a cracked window in a half-ruined wall, his reflection rippling; Mara_the_cartographer holds a compass, and the tin_fox sniffs the glass.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Mara_the_cartographer finds the old castle gate hidden by rubble.",
      "visual_description": "Mara_the_cartographer brushes dust from a carved stone gate half-buried under fallen masonry, her compass glowing faintly; the tin_fox digs at the base.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The oracle_lamp warns of a cursed tower ahead.",
      "visual_description": "The oracle_lamp flickers, its single eye widening as it speaks; behind it, a twisted spire looms, wrapped in shadow; the glass_diver and Mara_the_cartographer listen intently.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping_tax_collector is prodded awake for a key.",
      "visual_description": "The tin_fox nudges the sleeping_tax_collector's ledger pillow; he stirs, stamped papers fluttering, while Mara_the_cartographer looks on impatiently.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The glass_diver swims through a mirror into a sealed chamber.",
      "visual_description": "The glass_diver steps into a tall, cracked mirror and emerges inside a dusty room, his coat reflecting the city lights; Mara_the_cartographer watches through the glass.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of dragons color the ruined streets.",
      "visual_description": "The group walks past a wall painted with a faded serpent-like silhouette; the oracle_lamp casts a nervous glow, and the tin_fox freezes, ears twitching.",
      "characters": ["oracle_lamp", "tin_fox", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "Old royal banners hang from a broken spire.",
      "visual_description": "A torn banner with a faded emblem flutters from a leaning tower; the tin_fox climbs a rubble pile to get a better view, while Mara_the_cartographer notes the symbol.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Frightened townspeople are nowhere to be seen.",
      "visual_description": "An empty market square with overturned carts and abandoned stalls; the glass_diver peers through a window, seeing only dust; the oracle_lamp whispers that they fled long ago.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march through a distant plaza.",
      "visual_description": "From behind a broken colonnade, the group watches a line of figures in dented plate armor march in unison, their helmets hiding any faces; the tin_fox crouches low.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The glass_diver distracts the patrol with a mirror trick.",
      "visual_description": "The glass_diver positions a shard of glass to reflect light, creating a false movement down a side street; the patrol turns and marches away, clanking.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door refuses to open for the rescuers.",
      "visual_description": "A stone door carved with shifting runes stands at the end of a corridor; the glass_diver tries to swim through but is repelled; Mara_the_cartographer examines her map.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle_lamp solves the door's riddle.",
      "visual_description": "The oracle_lamp's flame brightens as it recites a forgotten phrase, and the runes align; the door grinds open, revealing a dark passage.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping_tax_collector finds a useful stamp amid the rubble.",
      "visual_description": "The sleeping_tax_collector, still half-asleep, picks up a fallen stamp from the floor; the tin_fox sniffs it, and Mara_the_cartographer realizes it can disenchant locks.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The final corridor is lined with cursed mirrors.",
      "visual_description": "A narrow hallway where every wall is a mirror showing distorted versions of the group; the glass_diver leads, stepping carefully to avoid being trapped.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The rescue reaches the captive in the tower's heart.",
      "visual_description": "A small circular room at the top of the tower, where a figure sits on a stone dais; the glass_diver approaches, removing his helmet; the oracle_lamp illuminates the scene.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The group flees across a crumbling bridge.",
      "visual_description": "A stone bridge spans a chasm, with pieces falling into darkness; the tin_fox darts ahead, the sleeping_tax_collector stumbles, and the glass_diver helps him up; the oracle_lamp lights the way.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the dawn outside the ruined city.",
      "visual_description": "The group stands on a hill overlooking the ruined city as the sun rises, the tattered banners and towers silhouetted; the glass_diver reflects the light, and the oracle_lamp dims.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

